	state: Mutex<EventState>,
	flags: EventFlags,
}

impl EventFd {
	pub fn new(initval: u64, flags: EventFlags) -> Self {
		debug!("Create EventFd {initval}, {flags:?}");
		Self {
			state: Mutex::new(EventState::new(initval)),
			flags,
		}
	}
}

