					Poll::Pending
				} else if event
					.intersects(PollEvent::POLLOUT | PollEvent::POLLWRNORM | PollEvent::POLLWRBAND)
				{
					guard.write_queue.push_back(cx.waker().clone());
					Poll::Pending
				} else {
					Poll::Ready(Ok(ret))
				}
			} else {
				Poll::Ready(Ok(ret))
			}
		})
		.await
	}
}

